function numberOfGoodSubsets(nums) {
  // Try every subset of the values other than 1, checking its prime factors
  // directly; each good one can be combined with any choice of the 1s.
  const factor = (v) => {
    const primes = [];
    for (let d = 2; v > 1; d++) {
      while (v % d === 0) {
        primes.push(d);
        v /= d;
      }
    }
    return primes;
  };
  const others = nums.filter(v => v !== 1).map(factor);
  const ones = nums.length - others.length;
  let good = 0;
  for (let pick = 1; pick < (1 << others.length); pick++) {
    const used = new Set();
    let ok = true;
    for (let i = 0; i < others.length && ok; i++) {
      if (!((pick >> i) & 1)) continue;
      for (const prime of others[i]) {
        if (used.has(prime)) ok = false;
        used.add(prime);
      }
    }
    if (ok) good++;
  }
  const mod = 1000000007n;
  let ways = BigInt(good) % mod;
  for (let i = 0; i < ones; i++) ways = (ways * 2n) % mod;
  return Number(ways);
}

